import {attackEligible} from './expedition-immunity.mjs';
import {offbeatEligible} from './expedition-offbeat.mjs';
import {POS,positionOrderAllowed} from './expedition-data.mjs';import {removableBuffs} from './expedition-unravel.mjs';
export const DEFAULT_ATTACK_ORDER=Object.freeze(Object.keys(POS));
export const POSITION_PRIORITY_RULE='仅“按个人阵位优先”的远程、法术、心理指令使用此顺序；每次从第一组合法存活敌人中按原上限选取，不跨阵位补齐，不预抽随机数。显式阵位、职责追击和近战仍沿原规则；群攻数量不足会检查后备，不自动改选后来人数更多的阵位。';
export function validateAttackOrder(plan){if(!Object.hasOwn(plan,'attackOrder'))return;const value=plan.attackOrder;if(!Array.isArray(value)||value.length!==5||new Set(value).size!==5||value.some(pos=>!Object.hasOwn(POS,pos)))throw Error('远攻阵位优先须完整包含五个不同阵位');}
export function attackOrder(plan){validateAttackOrder(plan);return [...(plan.attackOrder||DEFAULT_ATTACK_ORDER)];}
export function moveAttackOrder(plan,index,delta){if(!Number.isInteger(index)||![-1,1].includes(delta)||index<0||index>4||index+delta<0||index+delta>4)throw Error('阵位移动无效');const result=attackOrder(plan);[result[index],result[index+delta]]=[result[index+delta],result[index]];return result;}
export function positionPriorityDecision(actor,units,skill){if(!positionOrderAllowed(skill))throw Error('此技能不支持远攻阵位优先');const order=attackOrder(actor),pool=units.filter(u=>u.hp>0&&u.side!==actor.side&&attackEligible(u,skill)&&(!skill.dispel||removableBuffs(u).length)&&(!skill.actionDamp||offbeatEligible(u))),candidates=order.map(pos=>({pos,count:pool.filter(u=>u.pos===pos).length})),first=candidates.find(c=>c.count>0);return {order,candidates,selectedPosition:first?.pos||null,available:Math.min(first?.count||0,skill.max),limit:skill.max,rule:POSITION_PRIORITY_RULE};}
export const attackOrderLabel=plan=>attackOrder(plan).map(pos=>POS[pos]).join(' → ');
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function positionPriorityEvidenceView(event){const p=event?.detail?.positionPriority;if(!p)return '';return `<section class=position-priority-proof><h3>实际阵位优先</h3><p>${p.order.map(pos=>POS[pos]).join(' → ')}</p><p>当时合法候选：${p.candidates.map(c=>POS[c.pos]+' '+c.count+'名').join('；')}。${p.selectedPosition?'首组选中'+POS[p.selectedPosition]+'，技能人数上限'+p.limit+'。':'没有合法存活敌人。'}</p><small>${esc(POSITION_PRIORITY_RULE)}</small></section>`;}
export function attackOrderEditor(plan,inheritance='',canReset=false){const order=attackOrder(plan),active=plan.main.some(r=>r.target==='priority');return `<section class=attack-priority-editor><h3>远攻阵位优先 ${inheritance}</h3><details ${active?'open':''}><summary>${active?'本范围有指令使用此顺序':'展开排序 · 仅显式选用后生效'}</summary><p>只供目标选为“按个人阵位优先”的远程、法术和心理指令使用。近战、指定阵位及职责追击保持原规则；排序不会自动改动指令。</p>${order.map((pos,i)=>`<div class=order-row data-priority-position="${pos}"><span>${i+1} · ${POS[pos]}</span><div><button data-attack-order="${i}:-1" ${i===0?'disabled':''} aria-label="上移${POS[pos]}">↑</button> <button data-attack-order="${i}:1" ${i===4?'disabled':''} aria-label="下移${POS[pos]}">↓</button></div></div>`).join('')}${canReset?'<button data-attack-order-reset>恢复默认阵位顺序</button>':''}</details></section>`;}
